import{_ as t,c as o,o as r,ag as a}from"./chunks/framework.dvv-DFtf.js";const h=JSON.parse('{"title":"Resource List","description":"","frontmatter":{},"headers":[],"relativePath":"features/resource-list.md","filePath":"features/resource-list.md"}'),c={name:"features/resource-list.md"};function s(d,e,i,l,n,u){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="resource-list" tabindex="-1">Resource List <a class="header-anchor" href="#resource-list" aria-label="Permalink to &quot;Resource List&quot;">​</a></h1><p>The Resource List view lets you browse and manage any type of Kubernetes resource with powerful filtering and actions.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>Access the Resource List by selecting a resource type from the header with the resource type selector (<code>Opt+R</code>). This view displays all resources of a specific type in your selected namespace.</p><h2 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h2><h3 id="resource-type-selector" tabindex="-1">Resource Type Selector <a class="header-anchor" href="#resource-type-selector" aria-label="Permalink to &quot;Resource Type Selector&quot;">​</a></h3><p>Quickly switch between resource types:</p><ul><li>Press <code>Opt+R</code> (or <code>:</code>) to open the resource type selector</li><li>Type to filter available resource types</li><li>Supports all standard Kubernetes resources</li><li>Works with Custom Resource Definitions (CRDs)</li></ul><h3 id="namespace-selector" tabindex="-1">Namespace Selector <a class="header-anchor" href="#namespace-selector" aria-label="Permalink to &quot;Namespace Selector&quot;">​</a></h3><p>Switch the active namespace from the header:</p><ul><li>Press <code>Opt+N</code> to focus the namespace selector</li><li>Type to filter available namespaces</li><li>Pick a namespace from the dropdown to switch</li></ul><p>If a namespace has a <a href="./../configuration.html#namespace-labels">label</a> configured, a short badge is shown as a prefix inside the selector, while the input itself holds only the real namespace name. This keeps the field readable and means copying the value yields the actual Kubernetes namespace name, not the helper label. You can still filter by the label: type part of the label and the dropdown narrows to the matching namespaces.</p><h3 id="filtering" tabindex="-1">Filtering <a class="header-anchor" href="#filtering" aria-label="Permalink to &quot;Filtering&quot;">​</a></h3><p>Filter resources by name using the filter input:</p><ul><li>Type <code>/</code> and then type any text filter</li><li>Press <code>Esc</code> to clear the filter</li><li>Filter applies instantly as you type</li></ul><h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><p>Each resource type displays relevant columns.</p><h3 id="context-sensitive-actions" tabindex="-1">Context-Sensitive Actions <a class="header-anchor" href="#context-sensitive-actions" aria-label="Permalink to &quot;Context-Sensitive Actions&quot;">​</a></h3><p>Actions available depend on the resource type selected, for example:</p><p><strong>Deployments:</strong></p><ul><li>View Pods (<code>Enter</code>)</li><li>Describe (<code>D</code>)</li><li>Edit (<code>E</code>)</li><li>View Logs (<code>L</code>)</li><li>Rolling Restart (<code>R</code>)</li><li>Scale (<code>S</code>)</li><li>Delete (<code>Del</code>)</li></ul><p><strong>Pods:</strong></p><ul><li>View Containers (<code>Enter</code>)</li><li>Describe (<code>D</code>)</li><li>Edit (<code>E</code>)</li><li>View Logs (<code>L</code>)</li><li>Port Forward (<code>F</code>)</li><li>Shell (<code>S</code>)</li><li>Delete (<code>Del</code>)</li></ul><p><strong>Services:</strong></p><ul><li>View Pods (<code>Enter</code>)</li><li>Describe (<code>D</code>)</li><li>Edit (<code>E</code>)</li><li>Port Forward (<code>F</code>)</li><li>Delete (<code>Del</code>)</li></ul><h3 id="jump-to-related-resources" tabindex="-1">Jump to Related Resources <a class="header-anchor" href="#jump-to-related-resources" aria-label="Permalink to &quot;Jump to Related Resources&quot;">​</a></h3><p>Press <code>J</code> to open the Jump menu and quickly navigate to related resources:</p><ul><li>From a Deployment → Jump to its ReplicaSets, HorizontalPodAutoscalers, HTTPProxies, etc.</li><li>From a Service → Jump to Endpoints, Events, etc.</li></ul><h2 id="keyboard-shortcuts" tabindex="-1">Keyboard Shortcuts <a class="header-anchor" href="#keyboard-shortcuts" aria-label="Permalink to &quot;Keyboard Shortcuts&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Shortcut</th><th>Action</th></tr></thead><tbody><tr><td><code>↑</code> <code>↓</code></td><td>Navigate list</td></tr><tr><td><code>Ctrl+R</code></td><td>Refresh list manually</td></tr><tr><td><code>Esc</code></td><td>Back to previous view</td></tr><tr><td><code>Enter</code></td><td>Context-specific action (pods, containers)</td></tr><tr><td><code>D</code></td><td>Describe resource</td></tr><tr><td><code>E</code></td><td>Edit resource</td></tr><tr><td><code>L</code></td><td>View logs</td></tr><tr><td><code>F</code></td><td>Port forward, view port forwards</td></tr><tr><td><code>S</code></td><td>Scale (deployments) / Shell (pods, containers)</td></tr><tr><td><code>R</code></td><td>Rolling restart (deployments)</td></tr><tr><td><code>Del</code></td><td>Delete resource</td></tr><tr><td><code>J</code></td><td>Jump to related resource</td></tr><tr><td><code>Opt+R</code> or <code>:</code></td><td>Change resource type</td></tr><tr><td><code>Opt+C</code></td><td>Change context</td></tr><tr><td><code>Opt+N</code></td><td>Change namespace</td></tr><tr><td><code>/</code></td><td>Focus on filter input</td></tr></tbody></table><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">Quick change Resource, Context, Namespace</p><p>Press <code>Opt+R</code> to open the quick resource switcher. Type the resource type name and press Enter. Similarly, for Context and Namespace.</p></div><div class="tip custom-block"><p class="custom-block-title">Read-Only Mode</p><p>In read-only contexts, modifying actions (Edit, Delete, Scale) are disabled to prevent accidental changes. You can set <code>readOnly: true</code> in configuration to start in readonly mode.</p></div>',33)])])}const m=t(c,[["render",s]]);export{h as __pageData,m as default};
